content:
{
  "style": "Hiện đại - tối giản (Modern minimalist): đường nét sạch, bố cục trật tự, vật liệu trung tính và tương phản nhẹ",
  "area_type": "Sân vườn nhỏ (sân sau/tiền sân), diện tích hạn chế, ưu tiên bố cục gọn và dễ bảo trì",
  "main_elements": [
    {
      "element": "Bãi cỏ",
      "description": "mảng cỏ thấp làm nền chính, tạo cảm giác mở và mát"
    },
    {
      "element": "Lối đi đá",
      "description": "pavers/ván đá lớn bố trí tách rời hoặc liên tục, khe sỏi hoặc cỏ giữa các tấm"
    },
    {
      "element": "Cây xanh thấp",
      "description": "thảm phủ, bụi thấp và các khóm cỏ cảnh cao tối đa 0.6 m"
    },
    {
      "element": "Hồ nước nhỏ",
      "description": "hồ lót bạt hoặc bê tông nhỏ đặt lệch tâm làm điểm nhấn và phản chiếu"
    },
    {
      "element": "Đèn sân vườn",
      "description": "đèn lối đi, đèn âm đất cho cây và hồ, ánh sáng ấm, tiết kiệm năng lượng"
    }
  ],
  "plants": [
    {
      "name": "Cỏ Zoysia (Zoysia matrella)",
      "role": "bãi cỏ",
      "height": "2-4 cm",
      "notes": "mặt cắt gọn, chịu chân đi, phù hợp sân nhỏ"
    },
    {
      "name": "Mạch môn (Ophiopogon japonicus)",
      "role": "thảm phủ/viền lối đi",
      "height": "10-20 cm",
      "notes": "độ phủ dày, nét hiện đại, dễ chăm"
    },
    {
      "name": "Cỏ cảnh thấp (Pennisetum alopecuroides hoặc Carex spp.)",
      "role": "điểm nhấn mềm mại dọc lối đi và ven hồ",
      "height": "30-60 cm",
      "notes": "tạo chuyển động và kết cấu"
    },
    {
      "name": "Bụi tròn thấp (ví dụ Buxus microphylla hoặc tương đương địa phương)",
      "role": "điểm nhấn kiến trúc, viền",
      "height": "30-50 cm",
      "notes": "cắt tỉa định hình, tạo đường nét"
    },
    {
      "name": "Dương xỉ/nhóm cây ưa ẩm (ví dụ Nephrolepis spp.)",
      "role": "góc ẩm quanh hồ",
      "height": "20-50 cm",
      "notes": "tăng cảm giác tự nhiên, che bờ hồ mềm mại"
    }
  ],
  "materials": {
    "path": "pavers chữ nhật lớn (bê tông nhuộm xám hoặc đá bazan) với khe sỏi mịn hoặc cỏ giữa các tấm",
    "lawn": "cỏ Zoysia trên lớp đất thoát nước tốt, có hệ thống tưới cơ bản",
    "pond": "lót EPDM hoặc bê tông chống thấm, viền đá mài hoặc đá tự nhiên",
    "edging": "viền thép corten hoặc đá granite mảnh tạo đường nét rõ",
    "mulch": "vật liệu hữu cơ hoặc sỏi trang trí cho bồn cây"
  },
  "lighting": {
    "types": [
      "đèn cột thấp/bollard cho lối đi",
      "đèn âm đất (uplight) cho cây và bờ hồ",
      "đèn nhấn cạnh hồ/underwater light nhẹ"
    ],
    "color_temp": "2700-3000K (ánh sáng ấm)",
    "spacing": "đèn lối đi mỗi 1.2-1.5 m; uplight cách cây 0.5-1 m",
    "specs": "đèn LED ngoài trời IP65, tiết kiệm năng lượng, điều chỉnh độ sáng được"
  },
  "mood": "Tối giản, tĩnh lặng, thư giãn; cân bằng giữa yếu tố cứng (đá, bê tông) và mềm (cỏ, cây)",
  "layout_suggestion": {
    "proportion": "áp dụng quy tắc một phần ba: hồ ~1/3, bãi cỏ ~1/3, lối đi + bồn cây ~1/3",
    "pond_placement": "đặt lệch tâm về một bên (theo quy tắc 1/3) để tạo điểm nhấn và chiều sâu, kết hợp bồn ẩm quanh hồ",
    "path_layout": "lối đi lát đá uốn nhẹ từ lối vào đến vùng nhìn chính, dùng pavers lớn cách đều với khe sỏi hoặc cỏ",
    "planting_zones": "thảm phủ thấp dọc lề lối đi; bụi tròn gần rìa bãi cỏ; cỏ cảnh và dương xỉ bố trí ven hồ",
    "dimensions_guides": "hồ đường kính 1.5-3 m; paver 60x30–80x40 cm; lối đi rộng 0.8-1.2 m; khoảng cách trồng cây thấp 30-50 cm",
    "maintenance_notes": "ưu tiên cây dễ chăm, thiết kế thoát nước tốt quanh hồ, đặt nguồn điện an toàn cho đèn và bơm hồ, dự trữ lối tiếp cắt cỏ và bảo dưỡng định kỳ"
  }
}
